describe('Alert Dialog Interaction', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('#open-alert-dialog').click(); // Replace with the actual selector to open the alert dialog
    });

    it('should display the alert dialog and block interaction with the background', () => {
        cy.get('.alert-dialog').should('be.visible'); // Replace with the actual selector for the alert dialog
        cy.get('body').should('not.be.visible').and('not.have.class', 'interactable'); // Ensure background is not interactable
    });

    it('should close the alert dialog and allow interaction with the background', () => {
        cy.get('.alert-dialog .close-button').click(); // Replace with the actual selector for the close button
        cy.get('.alert-dialog').should('not.exist'); // Ensure the alert dialog is closed
        cy.get('body').should('be.visible').and('have.class', 'interactable'); // Ensure background is interactable again
    });
});
